function renderTaskResult(task: RenderTask, first: boolean, width: number, theme: RenderTheme): string {
  const prefix = first ? "    ⎿ " : "      ";
  const rawIcon = task.status === "completed" ? "✓" : task.status === "in_progress" ? "◉" :
