  goal_create: { required: ["description", "doneWhen", "doneWhenReviewed"], properties: { description: { type: "string", minLength: 1 }, doneWhen: { type: "string", minLength: 1 }, doneWhenReviewed: { type: "boolean", const: true }, idempotencyKey: id } },
